def is_valid(s: str) -> bool:
    # Initialize a stack to keep track of opening brackets
    stack = []
    # Dictionary to map closing brackets to their corresponding opening brackets
    bracket_map = {")": "(", "]": "[", "}": "{"}

    for char in s:
        if char in "([{":
            # Push opening brackets onto the stack
            stack.append(char)
        elif char == "*":
            # '*' can act as any bracket or nothing, so push all possibilities
            stack.extend(["(", ")", ""])
        else:
            # If stack is empty or top doesn't match the corresponding opening bracket, return False
            if not stack or (stack.pop() != bracket_map[char] and stack[-1] != "" if stack[-1] == "*" else True):
                return False

    # Check if all opening brackets have been closed
    while stack:
        if stack.pop() == "":
            continue  # '*' can close multiple brackets, ignore it
        if not stack or stack.pop() != "(":
            return False

    return True
